function solicitarReabrirPorPedido(pedido){
  $('acOrden').classList.remove('show');
  var reg=_registroGlobal(pedido, curCliente && curCliente.id);
  var h=getH();
  var local=null;
  for(var i=h.length-1;i>=0;i--){ if(h[i].pedido===pedido){ local=h[i]; break; } }
  var centro=(reg&&reg.centro)||(local&&local.centro)||'';
  var tienda=(local&&local.tienda)||'';
  _abrirDlgReabrir(pedido, centro, tienda);
}

function _abrirDlgReabrir(pedido, centro, tienda){
  $('dlgReabrirNum').textContent=pedido;
  $('dlgReabrirCentro').textContent=centro||tienda||'';
  window._reabrirPedido=pedido; window._reabrirCentro=centro;
  var esTecnicoPuro=window._sesion && window._sesion.rol==='tecnico' && !window._sesion.multiRol;
  var btnSi=$('dlgReabrirBtnSi'); var preg=$('dlgReabrirPregunta');
  if(esTecnicoPuro){
    if(btnSi) btnSi.innerHTML='&#128274; Solicitar reabrir';
    if(preg) preg.textContent='Esta orden está cerrada. Puedes solicitar a un administrador que la reabra.';
  } else {
    if(btnSi) btnSi.innerHTML='&#128275; Sí, reabrir';
    if(preg) preg.textContent='¿Quieres reabrirla y añadir un nuevo parte?';
  }
  $('dlgReabrir').classList.add('show');
}

function rQ(m){ return Math.ceil(m/15)*15; }

