// Al editar un parte ya guardado, estos campos identifican DE QUÉ parte se trata (misma
// incidencia, misma fecha, misma tienda, mismo número de parte, mismo tipo de trabajo y
// mismo festivo/normal que tenía) — se bloquean para que "Editar" nunca pueda convertirse
// en crear un parte distinto. Solo se puede tocar lo que un técnico normalmente introduce
// al generar un parte: horario, enlace, trabajadores, materiales y observaciones.
function _bloquearCamposIdentidadParte(){
  // El admin sí puede corregir el nº de parte de uno ya guardado (p.ej. al anular
  // uno y necesitar reordenar la numeración) — el técnico no, para que "Editar" nunca se
  // convierta en crear un parte distinto.
  var esAdmin = window._sesion && window._sesion.rol==='admin';
  var camposIdentidad = esAdmin
    ? ['fecha','pedido','centro','tienda','dir','tel']
    : ['fecha','pedido','centro','tienda','dir','tel','numParte'];
  camposIdentidad.forEach(function(id){
    var el=$(id);
    if(el){ el.readOnly=true; el.style.background='var(--surface2)'; el.style.color='var(--text2)'; }
  });
  document.querySelectorAll('#jobTgl button, #festivoTgl button').forEach(function(b){
    b.disabled=true; b.style.opacity='.55'; b.style.cursor='not-allowed';
  });
}
function _desbloquearCamposIdentidadParte(){
  ['fecha','pedido','centro','tienda','dir','tel','numParte'].forEach(function(id){
    var el=$(id);
    if(el){ el.readOnly=false; el.style.background=''; el.style.color=''; }
  });
  document.querySelectorAll('#jobTgl button, #festivoTgl button').forEach(function(b){
    b.disabled=false; b.style.opacity='1'; b.style.cursor='pointer';
  });
}
// ===== Módulo central de autorrelleno del formulario =====
// Todas las 'puertas de entrada' al formulario (historial, agenda, notificación de
// asignación, "¿Cómo seguimos?", etc.) deben pasar por aquí para rellenar los campos.
// Así el bloqueo de campos para técnico (y cualquier regla futura) vive en un solo
// sitio, en vez de repetirse — y arriesgarse a olvidarlo — en cada punto de entrada.
function _rellenarFormulario(datos){
  datos = datos || {};
  if(datos.centro!==undefined) $('centro').value=datos.centro||'';
  if(datos.tienda!==undefined) $('tienda').value=datos.tienda||'';
  if(datos.dir!==undefined) $('dir').value=datos.dir||'';
  if(datos.tel!==undefined) $('tel').value=datos.tel||'';
  if(datos.km){
    $('km').value=datos.km; $('kmE').value=datos.km; $('kmS').value='';
    if(datos.tr){ $('tr').value=datos.tr; $('trE').value=datos.tr; $('trS').value=''; }
  }
  if(datos.job){
    document.querySelectorAll('#jobTgl button').forEach(function(b){
      if(b.textContent.trim()===datos.job) setJob(datos.job,b);
    });
  }
  if(datos.catJob){
    document.querySelectorAll('#obrasMatTipoTgl button').forEach(function(b){
      if(b.textContent.trim()===datos.catJob) setObrasMatTipo(datos.catJob,b);
    });
  }
  if(datos.descripcion){
    var fd=$('fieldDescIncidencia'); var dd=$('descIncidencia');
    if(fd&&dd){ fd.style.display='block'; dd.value=datos.descripcion; }
  }
  var acO=$('acOrden'); if(acO) acO.classList.remove('show');
  var acC=$('acCentro'); if(acC) acC.classList.remove('show');
  _bloquearCamposAutorrellenados();
}
// Incidencia de un cliente NO Mercadona abierta con el nº de parte "0000" (la misma excepción de generar()):
// cada parte nuevo de esa incidencia sale con "0000" ya escrito. El técnico puede cambiarlo; si pone otro
// número, generar() comprueba que no esté repetido como siempre. Mira los partes guardados en este equipo y,
// con conexión, también los de Firestore (por si el primero lo hizo otro técnico). Nunca pisa lo ya escrito.
function _autoNumParte0000(pedido, centro){
  var campo=$('numParte');
  if(!pedido || !campo || _editIdx!==null || !curCliente || curCliente.tipo==='mercadona') return;
  var cid=curCliente.id;
  function aplicar(partes){
    if(campo.value.trim()) return;
    var orden=partes.filter(function(p){ return (p.clienteId||'mercadona')===cid && p.numParte; });
    if(!orden.length) return;
    orden.sort(function(a,b){ return (a.fecha||'').localeCompare(b.fecha||'') || ((tm(a.arr)||0)-(tm(b.arr)||0)); });
    if(orden[0].numParte==='0000') campo.value='0000';
  }
  var locales=getH().filter(function(p){ return p.pedido===pedido && (p.centro||'')===(centro||''); });
  aplicar(locales);
  if(typeof _db!=='undefined' && _db){
    _db.collection('partes').where('pedido','==',pedido).where('centro','==',centro||'').get().then(function(snap){
      aplicar(locales.concat(snap.docs.map(function(d){ return d.data(); })));
    }).catch(function(e){ console.warn('Nº parte 0000: no se pudo consultar Firestore', e); });
  }
}
function rellenarDatos(idx, soloOrdenActiva){
  var h=getH(); var r=h[idx]; if(!r) return;
  // Descripción de la incidencia: tomar la del último parte de esta misma orden
  // (por si se actualizó en un parte más reciente que el que se pasó por idx)
  var mismaOrden=h.filter(function(x){ return x.pedido===r.pedido && x.centro===r.centro && (x.clienteId||'mercadona')===(r.clienteId||'mercadona'); });
  mismaOrden.sort(function(a,b){ return (a.fecha||'').localeCompare(b.fecha||''); });
  var ultimo=mismaOrden[mismaOrden.length-1]||r;
  _rellenarFormulario({
    centro:r.centro, tienda:r.tienda, dir:r.dir, tel:r.tel, km:r.km, tr:r.tr,
    job: soloOrdenActiva?r.job:null,
    catJob: soloOrdenActiva?r.catJob:null,
    descripcion: ultimo.descIncidencia||ultimo.averiaReportada||''
  });
  if(soloOrdenActiva) _autoNumParte0000(r.pedido, r.centro);
}
function rellenarDesdeAgenda(clienteId,centro){
  var ag=agendaBuscar(clienteId,centro); if(!ag) return;
  _rellenarFormulario({ centro:ag.centro, tienda:ag.tienda, dir:ag.dir, tel:ag.tel, km:ag.km, tr:ag.tr });
}

