function tl(a,b){ return '('+fT(a)+') - ('+fT(b)+')'; }

function tm(x){ if(!x) return 0; var p=x.split(':'); return +p[0]*60+(+p[1]); }

function verCentros(){
  var h=getHVisible();
  if(curCliente)h=h.filter(function(r){return (r.clienteId||'mercadona')===curCliente.id;});
  // Determine which orders are finalized (last parte is terminado)
  var allH=h.slice();
  var ordenEstado={};
  var ordenPartes={};
  allH.forEach(function(r){
    var k=r.pedido+'||'+(r.centro||'');
    if(!ordenPartes[k])ordenPartes[k]=[];
    ordenPartes[k].push(r);
  });
  Object.keys(ordenPartes).forEach(function(k){
    var ps=ordenPartes[k].slice().sort(function(a,b){return a.fecha.localeCompare(b.fecha);});
    ordenEstado[k]=ps[ps.length-1].estado||'terminado';
  });
  // Only show finalized orders
  h=h.filter(function(r){
    var k=r.pedido+'||'+(r.centro||'');
    return ordenEstado[k]==='terminado';
  });
  var centrosMap={};
  // Count ALL partes per order, not just terminado ones
  allH.forEach(function(r){
    var k2=r.pedido+'||'+(r.centro||'');
    if(ordenEstado[k2]!=='terminado') return;
    var k=r.centro||'sin-centro';
    if(!centrosMap[k])centrosMap[k]={centro:k,tienda:r.tienda,partes:0,ordenes:{},fechaMax:r.fecha};
    centrosMap[k].tienda=r.tienda;centrosMap[k].partes++;
    centrosMap[k].ordenes[r.pedido+'||'+k]=1;
    if(!centrosMap[k].fechaMax||r.fecha>centrosMap[k].fechaMax)centrosMap[k].fechaMax=r.fecha;
  });
  _centrosCache=Object.values(centrosMap).sort(function(a,b){return b.fechaMax.localeCompare(a.fechaMax);});
  var html=_centrosCache.length?_centrosCache.map(function(c,i){
    var nInc=Object.keys(c.ordenes).length,nP=c.partes;
    return '<div class="hist-item" onclick="selCentro('+i+')"><div><div class="hi-title">&#127978; '+c.tienda+'</div><div class="hi-sub">'+nInc+' incidencia'+(nInc===1?'':'s')+' &middot; '+nP+' parte'+(nP===1?'':'s')+'</div></div><div class="hi-date">'+c.centro+'</div></div>';
  }).join(''):'<div class="empty"><div class="empty-ico">&#9989;</div><div>No hay órdenes finalizadas.</div></div>';
  $('centrosList').innerHTML=html;
  histShow(['centrosView']);
}

function verIncidenciasCentro(centro){
  _curCentroFin=centro;
  var h=getHVisible();
  if(curCliente)h=h.filter(function(r){return (r.clienteId||'mercadona')===curCliente.id;});
  // Get all partes for this centro
  var allForCentro=h.slice();
  allForCentro=allForCentro.filter(function(r){return r.centro===centro;});
  // Determine which orders are finalized
  var ordFinalized={};
  var ordPartes={};
  allForCentro.forEach(function(r){
    var k=r.pedido+'||'+centro;
    if(!ordPartes[k])ordPartes[k]=[];
    ordPartes[k].push(r);
  });
  Object.keys(ordPartes).forEach(function(k){
    var ps=ordPartes[k].slice().sort(function(a,b){return a.fecha.localeCompare(b.fecha);});
    if((ps[ps.length-1].estado||'terminado')==='terminado') ordFinalized[k]=1;
  });
  // Use all partes of finalized orders
  h=allForCentro.filter(function(r){return ordFinalized[r.pedido+'||'+centro];});
  var tienda=allForCentro.length?allForCentro[allForCentro.length-1].tienda:'';
  $('incCentroCard').innerHTML='<div style="font-weight:700;font-size:.95rem;">&#127978; '+tienda+'</div><div style="font-size:.76rem;color:var(--text2);margin-top:2px;">Centro '+centro+' &middot; '+h.length+' parte'+(h.length===1?'':'s')+'</div>';
  var ordenesMap={};
  h.forEach(function(r){
    var k=r.pedido+'||'+centro;
    if(!ordenesMap[k])ordenesMap[k]={pedido:r.pedido,job:r.job,actObras:r.actObras||null,partes:[],fechaMin:r.fecha,fechaMax:r.fecha};
    ordenesMap[k].partes.push(r);
    if(r.fecha<ordenesMap[k].fechaMin)ordenesMap[k].fechaMin=r.fecha;
    if(r.fecha>ordenesMap[k].fechaMax)ordenesMap[k].fechaMax=r.fecha;
  });
  window._incidenciasCache=Object.values(ordenesMap).sort(function(a,b){return b.fechaMax.localeCompare(a.fechaMax);});
  var html=window._incidenciasCache.map(function(o,i){
    var f1=o.fechaMin.split('-').reverse().join('/'),f2=o.fechaMax.split('-').reverse().join('/');
    var fr=f1===f2?f1:f1+' → '+f2;
    var titulo=o.actObras?o.actObras+' &middot; '+o.job:'Orden '+o.pedido+' &middot; '+o.job;
    return '<div class="hist-item" onclick="selIncidencia('+i+')"><div><div class="hi-title">&#128203; '+titulo+'</div><div class="hi-sub">'+fr+' &middot; '+o.partes.length+' parte'+(o.partes.length===1?'':'s')+'</div></div><span style="color:var(--text3);">&#8250;</span></div>';
  }).join('');
  $('incidenciasList').innerHTML=html||'<div class="empty">Sin incidencias.</div>';
  histShow(['incidenciasView']);
}

function initApp(){
  // (la comprobación de versión se arranca al final del archivo, en su propio bloque <script>)
  // Migrar técnicos de partes antiguos al cargar
  setTimeout(migrarTecnicos, 500);
  var h=getH();
  catActualizarBadge();
  var mod=false;
  h.forEach(function(r){
    if(!r.estado){r.estado='terminado';mod=true;}
    if(!r.clienteId){r.clienteId='mercadona';mod=true;}
    // Corregir dietas: debe ser igual al número de trabajadores
    if(r.dieta && r.roles && r.roles.length > 0){
      var nTrab = r.roles.length;
      (r.codigos||[]).forEach(function(c){
        if(c.u==='dieta' && c.v !== nTrab){ c.v = nTrab; mod=true; }
      });
    }
  });
  if(mod) setH(h);
}
var ICON_SRC = "data:image/png;base64,";

// IRV → ❄️ → IRV → ⚡ → IRV → ❄️ → IRV → ⚡ → IRV (parpadea 5s)
var SEQUENCE = [
  { isIRV:true },
  { isIRV:false, emoji:"❄️", bg:"linear-gradient(145deg,#0ea5e9,#0369a1)" },
  { isIRV:true },
  { isIRV:false, emoji:"⚡", bg:"linear-gradient(145deg,#1e1b4b,#3730a3)" },
  { isIRV:true },
  { isIRV:false, emoji:"❄️", bg:"linear-gradient(145deg,#0ea5e9,#0369a1)" },
  { isIRV:true },
  { isIRV:false, emoji:"⚡", bg:"linear-gradient(145deg,#1e1b4b,#3730a3)" },
  { isIRV:true, blink:true },  // último IRV — parpadea
];

// Textos: aparecen en flip 1, 3, 5
var TEXT_AT = { 1:"txt-irv", 3:"txt-sol", 5:"txt-med" };

var HALF  = 280;
var PAUSE = 650;

function renderFace(face) {
  var coin = document.getElementById("coin");
  if (!coin) return;
  coin.classList.remove("blinking");
  if (face.isIRV) {
    coin.style.background = "#fff";
    coin.innerHTML = "<img src='" + ICON_SRC + "' style='width:100%;height:100%;object-fit:cover;border-radius:26px;'>";
  } else {
    coin.style.background = face.bg;
    coin.innerHTML = "<span style='font-size:72px;line-height:1;'>" + face.emoji + "</span>";
  }
}

function iniciarSplash(alTerminar) {
  document.body.style.overflow = "hidden";
  var splash = document.getElementById("splash");
  var coin   = document.getElementById("coin");
  if (!splash || !coin) { if (alTerminar) alTerminar(); return; }

  splash.classList.remove("fade-out");
  splash.style.pointerEvents = "auto";
  splash.style.display = "flex";
  splash.style.opacity = "1";

  ["txt-irv","txt-sol","txt-med"].forEach(function(id){
    document.getElementById(id).classList.remove("visible");
  });

  renderFace(SEQUENCE[0]);
  coin.style.transition = "none";
  coin.style.transform  = "scaleX(1)";

  var flipIdx = 0;

  function doFlip() {
    flipIdx++;

    if (flipIdx >= SEQUENCE.length) {
      // No hay más flips — ya estamos en el último IRV parpadeando
      return;
    }

    var nextFace = SEQUENCE[flipIdx];

    // Aplanar
    coin.style.transition = "transform " + HALF + "ms ease-in";
    coin.style.transform  = "scaleX(0)";

    setTimeout(function(){
      renderFace(nextFace);

      // Expandir
      coin.style.transition = "transform " + HALF + "ms ease-out";
      coin.style.transform  = "scaleX(1)";

      // Mostrar texto si corresponde
      if (TEXT_AT[flipIdx]) {
        setTimeout(function(){
          var el = document.getElementById(TEXT_AT[flipIdx]);
          if (el) el.classList.add("visible");
        }, HALF);
      }

      // Si es el último (blink) — parpadear 5s y luego salir
      if (nextFace.blink) {
        setTimeout(function(){
          // Parpadeo + crecimiento progresivo al ritmo del parpadeo (4s por ciclo)
          // Crecer de scale(1) a scale(20) en 5 ciclos de parpadeo = 20s... demasiado
          // Usamos 5s totales: el icono crece mientras parpadea
          var startTime = null;
          var BLINK_MS  = 4000;   // duración de un parpadeo
          var TOTAL_MS  = 6000;  // tiempo total hasta llenar pantalla
          var MAX_SCALE = 25;     // escala máxima para cubrir pantalla

          function animateStep(ts) {
            if (!startTime) startTime = ts;
            var elapsed = ts - startTime;
            var progress = Math.min(elapsed / TOTAL_MS, 1);

            // Escala crece de 1 a MAX_SCALE
            var scale = 1 + (MAX_SCALE - 1) * progress;

            // Parpadeo: seno para opacidad oscilante al ritmo de BLINK_MS
            var blinkPhase = (elapsed % BLINK_MS) / BLINK_MS; // 0..1
            var opacity = 0.55 + 0.45 * Math.cos(blinkPhase * 2 * Math.PI); // 0.1..1

            coin.style.transition = "none";
            coin.style.transform  = "scale(" + scale + ")";
            coin.style.opacity    = opacity;

            if (progress < 1) {
              requestAnimationFrame(animateStep);
            } else if (alTerminar) {
              // Hay un callback esperando — no ocultar por cuenta propia, dejar que decida cuándo
              alTerminar();
            } else {
              // Pantalla cubierta — mostrar app
              splash.classList.add("fade-out");
              setTimeout(function(){
                var splashEl = document.getElementById("splash");
                if(splashEl) splashEl.style.display = 'none'; // Ocultar pero no eliminar — se reutiliza al login
                document.body.style.overflow = "";
                document.body.style.height   = "";
              }, 600);
            }
          }

          requestAnimationFrame(animateStep);
        }, HALF);
        return;
      }

      setTimeout(doFlip, PAUSE);
    }, HALF);
  }

  setTimeout(doFlip, 800);
}

iniciarSplash();

initApp();

// Limpieza automática: borrar partes finalizados con más de 24 meses
(function(){
  var h = getH();
  var hoy = new Date();
  var limite = new Date(hoy.getFullYear()-2, hoy.getMonth(), hoy.getDate());
  var limiteStr = limite.toISOString().slice(0,10);
  var antes = h.length;
  h = h.filter(function(r){
    // Nunca borrar los en ejecución
    if((r.estado||'terminado')==='en-ejecucion') return true;
    // Borrar solo finalizados con fecha anterior al límite
    return !r.fecha || r.fecha >= limiteStr;
  });
  if(h.length < antes){
    setH(h);
  }
})();

